for _,row in ipairs(Q.rows)do
 Q.byBadge[row.badgeID]=row
 for _,id in ipairs(row.questIDs)do Q.byQuest[id]=row end
 local m={key=row.key,title=row.title,activity=row.badgeID,questStory=true,quests=row.questIDs,source=row.sourceURL,claim=row.claim,variants={}}
 for index,a in ipairs(row.variants)do
  local definition={key=a.key,title=a.title,activity=row.badgeID,questStory=true,group=row.key,path=B.base..string.format('QuestMementos%02d.tga',a.sheet),slot=a.cell,source=row.sourceURL}
  m.variants[a.questID]=definition;B.memoryByKey[a.key]=definition;B.charms[a.key]=a.cell
  local c,r=(a.cell-1)%4,math.floor((a.cell-1)/4)
  local entry={id=a.key,kind='texture',ref=definition.path,category='memento.quest',source='warden-original-journal3',width=256,height=256,uv={c/4+.002,(c+1)/4-.002,r/4+.002,(r+1)/4-.002},fallback='Divider',crop='contain',notes=row.claim..'; reference knowledge does not grant the artwork.',playerSafe=true}
  K.entries[#K.entries+1]=entry;K.byID[a.key]=entry
