 end
 B.memories[#B.memories+1]=m
end
local function plain(t)return type(t)=='table'and getmetatable(t)==nil end
-- Existing VanCleef artwork is kept. Its proof follows the dungeon explicitly;
-- the distinct new third story object uses alternate quest168, not a duplicate.
Q.bonusByQuest={[166]={badgeID='activity-the-deadmines',key='quest-166',bonus=true,variants={{key='quest-166',questID=166}}}}
function Q.Record(e,s)
 if e.kind~='quest_turnin'or e.source~='QUEST_TURNED_IN'or e.character~=ns.Chronicle.Owner()then return end
 local d=e.details;if not plain(d)or d.baseline==true or d.scope=='native completed list; character/account attribution unknown'then return end
 local row=Q.byQuest[d.questID]or Q.bonusByQuest[d.questID];if not row then return end
 if s.questMementoProofs==nil then s.questMementoProofs={}end;if not plain(s.questMementoProofs)then return end
 local storageKey=row.bonus and row.badgeID..'/'..row.key or row.badgeID
 if s.questMementoProofs[storageKey]then return end
 local count=0;for _ in pairs(s.questMementoProofs)do count=count+1 end;if count>=Q.MAX_PROOFS then return end
 local variant=row.variants[1];for _,a in ipairs(row.variants)do if a.questID==d.questID then variant=a end end
 local temporal=plain(e.temporal)and e.temporal or{}
 local exact=temporal.basis~='baseline'and temporal.precision~='unknown'and temporal.occurrencePrecision~='unknown'
 local proof={key=variant.key,questID=d.questID,eventRef=e.id,observedAt=e.at,precision=exact and'observed quest turn-in'or'unknown original completion date'}
 if exact then proof.at=e.at end
 s.questMementoProofs[storageKey]=proof;s.revision=s.revision+1
 local b=s.badges[row.badgeID]
 if plain(b)then
  if row.bonus then b.quests[d.questID]=true;b.memoryProofs=b.memoryProofs or{};b.memoryProofs[row.key]=proof else b.questStoryProof=proof end
  ns.WardenMementos.RefreshBadge(e.character,s,b,e,true)
 end
 return true
end
function Q.Attach(s,b)
 local p=plain(s.questMementoProofs)and s.questMementoProofs[b.art]
 if plain(p)then b.questStoryProof=p end
 local bonus=plain(s.questMementoProofs)and s.questMementoProofs[b.art..'/quest-166']
 if plain(bonus)then b.quests[166]=true;b.memoryProofs=b.memoryProofs or{};b.memoryProofs['quest-166']=bonus end
end
